INSERT INTO public.capability_catalog(name,label,workspace,sensitive,scope_kinds) VALUES
 ('payroll-accruals.view','View private recorded hourly gross earnings','Finance',true,ARRAY['hub','person','country','region','city']),
 ('payroll-accruals.edit','Request reviewed hourly earnings and retained corrections','Finance',true,ARRAY['hub','person','country','region','city']);
-- Gross accounting and worker-wide time ownership, never net pay/payment.
-- The application computes the versioned earning plan; native guards bind it
-- to exact human review/current sources, enforce ledger conservation and own
-- exclusion ranges. This is not an independent SQL reimplementation of rates.
CREATE TABLE public.payroll_hourly_accruals(
 academy_id uuid NOT NULL,id uuid NOT NULL,person_id uuid NOT NULL,reference text NOT NULL CHECK(reference~'^[A-Z0-9][A-Z0-9._-]{0,63}$'),from_on date NOT NULL,through_on date NOT NULL,time_zone text NOT NULL,basis text NOT NULL CHECK(basis IN('actual','configured')),
 currency_id uuid NOT NULL,currency_version integer NOT NULL,unit_scale integer NOT NULL CHECK(unit_scale BETWEEN 0 AND 18),amount_minor numeric NOT NULL CHECK(amount_minor>0 AND amount_minor=trunc(amount_minor) AND amount_minor<1e38),
 posted_on date NOT NULL,due_on date NOT NULL,period_id uuid NOT NULL,period_version integer NOT NULL,expense_account uuid NOT NULL,expense_version integer NOT NULL,liability_account uuid NOT NULL,liability_version integer NOT NULL,
 input jsonb NOT NULL,source_snapshot jsonb NOT NULL,earning_plan jsonb NOT NULL,approval_id uuid NOT NULL,created_by uuid NOT NULL,void_id uuid,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(academy_id,id),UNIQUE(academy_id,person_id,reference),
 CHECK(from_on BETWEEN DATE '1900-01-01' AND DATE '9999-12-31' AND through_on BETWEEN from_on AND DATE '9999-12-31' AND through_on-from_on<=365 AND posted_on BETWEEN through_on AND DATE '9999-12-31' AND due_on BETWEEN through_on AND DATE '9999-12-31'),
 CHECK(jsonb_typeof(input)='object' AND octet_length(input::text)<=65536 AND jsonb_typeof(source_snapshot)='object' AND octet_length(source_snapshot::text)<=2500000 AND jsonb_typeof(earning_plan)='object' AND octet_length(earning_plan::text)<=2097152),
 FOREIGN KEY(academy_id,person_id) REFERENCES public.people(academy_id,id),FOREIGN KEY(academy_id,currency_id,currency_version) REFERENCES public.finance_currency_revisions(academy_id,currency_id,version),
 FOREIGN KEY(academy_id,period_id,period_version) REFERENCES public.finance_period_revisions(academy_id,period_id,version),FOREIGN KEY(academy_id,expense_account,expense_version) REFERENCES public.finance_account_revisions(academy_id,account_id,version),FOREIGN KEY(academy_id,liability_account,liability_version) REFERENCES public.finance_account_revisions(academy_id,account_id,version),
 FOREIGN KEY(academy_id,approval_id) REFERENCES public.approval_requests(academy_id,id),FOREIGN KEY(academy_id,created_by) REFERENCES public.people(academy_id,id),FOREIGN KEY(academy_id,id) REFERENCES public.finance_journals(academy_id,id) DEFERRABLE INITIALLY DEFERRED
);
CREATE TABLE public.payroll_hourly_voids(
 academy_id uuid NOT NULL,id uuid NOT NULL,accrual_id uuid NOT NULL,source_snapshot jsonb NOT NULL CHECK(jsonb_typeof(source_snapshot)='object' AND octet_length(source_snapshot::text)<=2500000),reason text NOT NULL CHECK(length(btrim(reason)) BETWEEN 1 AND 2000),approval_id uuid NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(academy_id,id),UNIQUE(academy_id,accrual_id),UNIQUE(academy_id,id,accrual_id),FOREIGN KEY(academy_id,accrual_id) REFERENCES public.payroll_hourly_accruals(academy_id,id),FOREIGN KEY(academy_id,approval_id) REFERENCES public.approval_requests(academy_id,id),FOREIGN KEY(academy_id,created_by) REFERENCES public.people(academy_id,id),FOREIGN KEY(academy_id,id) REFERENCES public.finance_journals(academy_id,id) DEFERRABLE INITIALLY DEFERRED
);
ALTER TABLE public.payroll_hourly_accruals ADD FOREIGN KEY(academy_id,void_id,id) REFERENCES public.payroll_hourly_voids(academy_id,id,accrual_id) DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE public.payroll_hourly_claims(
 academy_id uuid NOT NULL,accrual_id uuid NOT NULL,ordinal integer NOT NULL CHECK(ordinal BETWEEN 1 AND 1000),person_id uuid NOT NULL,start_ms bigint NOT NULL,end_ms bigint NOT NULL,release_id uuid,
 PRIMARY KEY(academy_id,accrual_id,ordinal),CHECK(end_ms>start_ms AND end_ms-start_ms<=368::bigint*86400000),
 FOREIGN KEY(academy_id,accrual_id) REFERENCES public.payroll_hourly_accruals(academy_id,id),FOREIGN KEY(academy_id,person_id) REFERENCES public.people(academy_id,id),FOREIGN KEY(academy_id,release_id,accrual_id) REFERENCES public.payroll_hourly_voids(academy_id,id,accrual_id) DEFERRABLE INITIALLY DEFERRED,
 EXCLUDE USING gist(academy_id WITH =,person_id WITH =,int8range(start_ms,end_ms,'[)') WITH &&) WHERE(release_id IS NULL)
);
CREATE INDEX hourly_accrual_worker ON public.payroll_hourly_accruals(academy_id,person_id,id);
CREATE TABLE public.payroll_hourly_entry_sources(
 academy_id uuid NOT NULL,accrual_id uuid NOT NULL,entry_id uuid NOT NULL,entry_version integer NOT NULL,person_id uuid NOT NULL,pricing_fingerprint text NOT NULL CHECK(pricing_fingerprint~'^[a-f0-9]{64}$'),release_id uuid,
 PRIMARY KEY(academy_id,accrual_id,entry_id),FOREIGN KEY(academy_id,accrual_id) REFERENCES public.payroll_hourly_accruals(academy_id,id),FOREIGN KEY(academy_id,entry_id,entry_version) REFERENCES public.session_time_revisions(academy_id,entry_id,version),FOREIGN KEY(academy_id,person_id) REFERENCES public.people(academy_id,id),FOREIGN KEY(academy_id,release_id,accrual_id) REFERENCES public.payroll_hourly_voids(academy_id,id,accrual_id) DEFERRABLE INITIALLY DEFERRED
);
CREATE INDEX hourly_entry_source_active ON public.payroll_hourly_entry_sources(academy_id,entry_id,pricing_fingerprint) WHERE release_id IS NULL;
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['payroll_hourly_accruals','payroll_hourly_voids','payroll_hourly_claims','payroll_hourly_entry_sources'] LOOP
 EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE public.%I FORCE ROW LEVEL SECURITY',t);
 EXECUTE format('CREATE POLICY tenant_boundary ON public.%I USING(academy_id=nullif(current_setting(''app.academy_id'',true),'''')::uuid) WITH CHECK(academy_id=nullif(current_setting(''app.academy_id'',true),'''')::uuid)',t);
 EXECUTE format('CREATE TRIGGER hourly_write BEFORE INSERT OR UPDATE OR DELETE ON public.%I FOR EACH STATEMENT EXECUTE FUNCTION public.guard_expense_commitment_write()',t);EXECUTE format('GRANT SELECT ON public.%I TO kavosh_runtime',t);
END LOOP;END $$;
GRANT INSERT(academy_id,id,person_id,reference,from_on,through_on,time_zone,basis,currency_id,currency_version,unit_scale,amount_minor,posted_on,due_on,period_id,period_version,expense_account,expense_version,liability_account,liability_version,input,source_snapshot,earning_plan,approval_id,created_by) ON public.payroll_hourly_accruals TO kavosh_runtime;
GRANT UPDATE(void_id) ON public.payroll_hourly_accruals TO kavosh_runtime;
GRANT INSERT(academy_id,id,accrual_id,source_snapshot,reason,approval_id,created_by) ON public.payroll_hourly_voids TO kavosh_runtime;
GRANT INSERT(academy_id,accrual_id,ordinal,person_id,start_ms,end_ms) ON public.payroll_hourly_claims TO kavosh_runtime;
GRANT UPDATE(release_id) ON public.payroll_hourly_claims TO kavosh_runtime;
GRANT INSERT(academy_id,accrual_id,entry_id,entry_version,person_id,pricing_fingerprint) ON public.payroll_hourly_entry_sources TO kavosh_runtime;
GRANT UPDATE(release_id) ON public.payroll_hourly_entry_sources TO kavosh_runtime;
CREATE FUNCTION public.lock_hourly_worker(p_person uuid) RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE tenant uuid:=nullif(current_setting('app.academy_id',true),'')::uuid;BEGIN
 IF tenant IS NULL THEN RETURN;END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended(tenant::text,8));PERFORM public.lock_finance_book();PERFORM pg_advisory_xact_lock_shared(hashtextextended(tenant::text,9));
 PERFORM pg_advisory_xact_lock(hashtextextended(tenant::text||':'||p_person::text,36));
END $$;
CREATE FUNCTION public.hourly_accounting_source(p_expense uuid,p_liability uuid,p_period uuid) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE tenant uuid:=nullif(current_setting('app.academy_id',true),'')::uuid;p record;accounts jsonb;BEGIN
 SELECT * INTO p FROM public.finance_periods WHERE academy_id=tenant AND id=p_period FOR SHARE;IF NOT FOUND THEN RETURN NULL;END IF;
 PERFORM id FROM public.finance_accounts WHERE academy_id=tenant AND id IN(p_expense,p_liability) ORDER BY id FOR SHARE;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'hubId',hub_id,'version',version,'kind',kind,'role',operational_role,'active',active,'currencyId',currency_id,'currencyVersion',currency_version,'unitScale',unit_scale) ORDER BY id),'[]'::jsonb) INTO accounts FROM public.finance_account_catalogue WHERE academy_id=tenant AND id IN(p_expense,p_liability);
 RETURN jsonb_build_object('accounts',accounts,'period',jsonb_build_object('id',p.id,'version',p.version,'state',p.state,'startsOn',p.starts_on::text,'endsOn',p.ends_on::text,'closedThrough',(SELECT max(ends_on)::text FROM public.finance_periods WHERE academy_id=tenant AND state='closed' AND active_closing_run_id IS NOT NULL)));
END $$;
CREATE FUNCTION public.hourly_accrual_source(i jsonb,p_exclude uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE tenant uuid:=nullif(current_setting('app.academy_id',true),'')::uuid;s jsonb;c jsonb;parties jsonb;a jsonb;BEGIN
 PERFORM public.lock_hourly_worker((i->>'personId')::uuid);
 s=public.payroll_preparation_source((i->>'personId')::uuid,(i->>'from')::date,(i->>'through')::date,i->>'timeZone');IF s IS NULL OR s->'oversized' IS DISTINCT FROM 'false'::jsonb THEN RETURN s;END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.start,x.end,x.accrual_id,x.ordinal),'[]'::jsonb) INTO c FROM(SELECT accrual_id,ordinal,start_ms::text start,end_ms::text "end" FROM public.payroll_hourly_claims WHERE academy_id=tenant AND person_id=(i->>'personId')::uuid AND release_id IS NULL AND(p_exclude IS NULL OR accrual_id<>p_exclude) AND int8range(start_ms,end_ms,'[)')&&int8range((s->>'windowStartMilliseconds')::bigint,(s->>'windowEndMilliseconds')::bigint,'[)') ORDER BY start_ms,end_ms,accrual_id,ordinal LIMIT 201) x;
 IF jsonb_array_length(c)>200 THEN RETURN jsonb_build_object('oversized',true);END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('engagementId',r.engagement_id,'version',r.version,'employerId',r.employer_id,'payeeId',r.payee_id,'classification',r.definition->>'classification') ORDER BY r.engagement_id,r.version),'[]'::jsonb) INTO parties FROM public.work_engagement_revisions r JOIN jsonb_array_elements(s->'terms') t ON r.engagement_id=(t->>'engagement_id')::uuid AND r.version=(t->>'version')::integer WHERE r.academy_id=tenant;
 a=public.hourly_accounting_source((i#>>'{expenseAccount,id}')::uuid,(i#>>'{liabilityAccount,id}')::uuid,(i#>>'{period,id}')::uuid);
 RETURN jsonb_build_object('payroll',s,'claims',c,'parties',parties,'accounting',a);
END $$;
CREATE FUNCTION public.hourly_void_source(p_accrual uuid,p_period uuid) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE b record;BEGIN
 SELECT * INTO b FROM public.payroll_hourly_accruals WHERE academy_id=nullif(current_setting('app.academy_id',true),'')::uuid AND id=p_accrual;IF NOT FOUND THEN RETURN NULL;END IF;PERFORM public.lock_hourly_worker(b.person_id);
 SELECT * INTO b FROM public.payroll_hourly_accruals WHERE academy_id=b.academy_id AND id=p_accrual FOR UPDATE;
 RETURN jsonb_build_object('before',jsonb_build_object('id',b.id,'personId',b.person_id,'voidId',b.void_id,'postedOn',b.posted_on::text,'currencyId',b.currency_id,'unitScale',b.unit_scale,'amountMinor',b.amount_minor::text,'expenseAccount',b.expense_account,'expenseVersion',b.expense_version,'liabilityAccount',b.liability_account,'liabilityVersion',b.liability_version),'accounting',public.hourly_accounting_source(b.expense_account,b.liability_account,p_period));
END $$;
CREATE FUNCTION public.hourly_plan_valid(p jsonb,s jsonb,p_basis text,p_currency uuid,p_amount numeric) RETURNS boolean LANGUAGE plpgsql STABLE SET search_path=pg_catalog AS $$ DECLARE actual_coverage int8multirange;paid_coverage int8multirange;prior_coverage int8multirange;claimed_coverage int8multirange;first_ms bigint;last_ms bigint;BEGIN
 IF p->>'engine' IS DISTINCT FROM 'hourly-gross-v2' OR p_basis NOT IN('actual','configured') OR jsonb_typeof(p->'segments') IS DISTINCT FROM 'array' OR jsonb_array_length(p->'segments') NOT BETWEEN 1 AND 1600 OR jsonb_typeof(p->'sourceAllocations') IS DISTINCT FROM 'array' OR jsonb_array_length(p->'sourceAllocations') NOT BETWEEN 1 AND 200 OR jsonb_typeof(p->'sourceAssessments') IS DISTINCT FROM 'array' OR jsonb_array_length(p->'sourceAssessments') NOT BETWEEN 1 AND 200 THEN RETURN false;END IF;
 first_ms=(s#>>'{payroll,windowStartMilliseconds}')::bigint;last_ms=(s#>>'{payroll,windowEndMilliseconds}')::bigint;
 IF jsonb_typeof(p->'sourceIdentities') IS DISTINCT FROM 'array' OR jsonb_array_length(p->'sourceIdentities') NOT BETWEEN 1 AND 200 OR(SELECT count(DISTINCT a->>'entryId') FROM jsonb_array_elements(p->'sourceAssessments') a)<>jsonb_array_length(p->'sourceIdentities') OR(SELECT count(DISTINCT a->>'entryId') FROM jsonb_array_elements(p->'sourceIdentities') a)<>jsonb_array_length(p->'sourceIdentities')
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(p->'sourceIdentities') a WHERE jsonb_typeof(a->'pricingFingerprint') IS DISTINCT FROM 'string' OR a->>'pricingFingerprint'!~'^[a-f0-9]{64}$' OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p->'sourceAssessments') x WHERE x->>'entryId'=a->>'entryId' AND x->'entryVersion'=a->'entryVersion')) THEN RETURN false;END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p->'segments') x WHERE jsonb_typeof(x->'start') IS DISTINCT FROM 'number' OR jsonb_typeof(x->'end') IS DISTINCT FROM 'number' OR jsonb_typeof(x->'rateMinor') IS DISTINCT FROM 'string' OR x->>'rateMinor'!~'^[0-9]{1,100}$' OR(x->>'start')::numeric<>trunc((x->>'start')::numeric) OR(x->>'end')::numeric<>trunc((x->>'end')::numeric)) THEN RETURN false;END IF;
 IF EXISTS(SELECT 1 FROM(SELECT (x->>'start')::bigint a,(x->>'end')::bigint b,lag((x->>'end')::bigint) OVER(ORDER BY(x->>'start')::bigint,(x->>'end')::bigint) previous_end FROM jsonb_array_elements(p->'segments') x) x WHERE a<first_ms OR b>last_ms OR b<=a OR a<previous_end) THEN RETURN false;END IF;
 IF(SELECT round(sum((x->>'rateMinor')::numeric*((x->>'end')::numeric-(x->>'start')::numeric))/3600000) FROM jsonb_array_elements(p->'segments') x) IS DISTINCT FROM p_amount THEN RETURN false;END IF;
 IF jsonb_typeof(p->'workAllocations') IS DISTINCT FROM 'array' OR jsonb_array_length(p->'workAllocations') NOT BETWEEN 1 AND 200 OR EXISTS(SELECT 1 FROM(SELECT value a FROM jsonb_array_elements(p->'sourceAllocations') UNION ALL SELECT value FROM jsonb_array_elements(p->'workAllocations')) x WHERE jsonb_typeof(a#>'{gross,minor}') IS DISTINCT FROM 'string' OR a#>>'{gross,minor}'!~'^[0-9]{1,38}$')
 OR(SELECT count(DISTINCT x->>'key') FROM jsonb_array_elements(p->'sourceAllocations') x)<>jsonb_array_length(p->'sourceAllocations') OR(SELECT count(DISTINCT x->>'engagementId') FROM jsonb_array_elements(p->'workAllocations') x)<>jsonb_array_length(p->'workAllocations') THEN RETURN false;END IF;
 IF(SELECT count(DISTINCT x->>'key') FROM jsonb_array_elements(p->'segments') x)<>jsonb_array_length(p->'sourceAllocations') THEN RETURN false;END IF;
 IF EXISTS(WITH sums AS(SELECT x->>'key' key,sum((x->>'rateMinor')::numeric*((x->>'end')::numeric-(x->>'start')::numeric)) n FROM jsonb_array_elements(p->'segments') x GROUP BY x->>'key'),
 ranked AS(SELECT key,trunc(n/3600000) base,row_number() OVER(ORDER BY mod(n,3600000) DESC,key COLLATE "C") rank,p_amount-sum(trunc(n/3600000)) OVER() residual FROM sums)
 SELECT 1 FROM ranked r WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p->'sourceAllocations') x WHERE x->>'key'=r.key AND(x#>>'{gross,minor}')::numeric=r.base+CASE WHEN r.rank<=r.residual THEN 1 ELSE 0 END)) THEN RETURN false;END IF;
 IF(SELECT count(DISTINCT x->>'engagementId') FROM jsonb_array_elements(p->'sourceAllocations') x)<>jsonb_array_length(p->'workAllocations') OR EXISTS(WITH sums AS(SELECT x->>'engagementId' id,sum((x#>>'{gross,minor}')::numeric) amount FROM jsonb_array_elements(p->'sourceAllocations') x GROUP BY x->>'engagementId') SELECT 1 FROM sums s WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p->'workAllocations') x WHERE x->>'engagementId'=s.id AND(x#>>'{gross,minor}')::numeric=s.amount)) THEN RETURN false;END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p->'segments') x WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p->'sourceAllocations') a WHERE a->>'key'=x->>'key')) THEN RETURN false;END IF;
 IF EXISTS(SELECT 1 FROM(SELECT value a FROM jsonb_array_elements(p->'sourceAllocations') UNION ALL SELECT value FROM jsonb_array_elements(p->'sourceAssessments')) a
 WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(s#>'{payroll,entries}') e WHERE e->>'id'=a.a->>'entryId' AND e->'version'=a.a->'entryVersion' AND e->>'person_id'=a.a->>'personId' AND e->>'hub_id'=a.a->>'hubId' AND e->>'class_id'=a.a->>'classId' AND e->>'session_id'=a.a->>'sessionId' AND e->>'assignment_id'=a.a->>'assignmentId' AND e->'assignment_version'=a.a->'assignmentVersion')
 OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(s#>'{payroll,terms}') t CROSS JOIN LATERAL jsonb_array_elements(t->'components') c WHERE t->>'engagement_id'=a.a->>'engagementId' AND t->'version'=a.a->'termsVersion' AND t->>'currency_id'=p_currency::text AND t->>'person_id'=a.a->>'personId' AND c->>'code'=a.a->>'componentCode' AND c->>'kind' IN('hourly','headcount_hourly'))) THEN RETURN false;END IF;
 SELECT coalesce(range_agg(int8range(greatest(first_ms,(extract(epoch FROM(e->>'starts_at')::timestamptz)*1000)::bigint),least(last_ms,(extract(epoch FROM(e->>'ends_at')::timestamptz)*1000)::bigint),'[)')),'{}'::int8multirange) INTO actual_coverage FROM jsonb_array_elements(s#>'{payroll,entries}') e
 WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(p->'sourceAssessments') a WHERE a->>'entryId'=e->>'id');
 SELECT coalesce(range_agg(int8range((x->>'start')::bigint,(x->>'end')::bigint,'[)')),'{}'::int8multirange) INTO paid_coverage FROM jsonb_array_elements(p->'segments') x;
 SELECT coalesce(range_agg(int8range((x->>'start')::bigint,(x->>'end')::bigint,'[)')),'{}'::int8multirange) INTO prior_coverage FROM jsonb_array_elements(s->'claims') x;
 SELECT coalesce(range_agg(int8range((x->>'start')::bigint,(x->>'end')::bigint,'[)')),'{}'::int8multirange) INTO claimed_coverage FROM jsonb_array_elements(p->'timeClaims') x;
 RETURN claimed_coverage IS NOT DISTINCT FROM((CASE WHEN p_basis='configured' THEN actual_coverage+paid_coverage ELSE actual_coverage END)-prior_coverage);
 EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR data_exception THEN RETURN false;
END $$;
CREATE FUNCTION public.guard_hourly_accrual() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE p record;s jsonb;e jsonb;l jsonb;a jsonb;w jsonb;target jsonb;BEGIN
 IF TG_OP='UPDATE' THEN IF OLD.void_id IS NOT NULL OR NEW.void_id IS NULL OR to_jsonb(NEW)-'void_id' IS DISTINCT FROM to_jsonb(OLD)-'void_id' THEN RAISE EXCEPTION 'HOURLY_ACCRUAL_IMMUTABLE' USING ERRCODE='23514';END IF;RETURN NEW;END IF;
 s=public.hourly_accrual_source(NEW.input);SELECT * INTO p FROM public.approval_requests WHERE academy_id=NEW.academy_id AND id=NEW.approval_id;w=s#>'{payroll,work,0}';
 target=jsonb_build_object('all',false,'hubs','[]'::jsonb,'people',jsonb_build_array(jsonb_build_object('id',w->>'person_id','hubId',w->'hub_id')),'workContext',jsonb_build_object('personId',w->>'person_id','hubId',w->'hub_id'));
 IF s IS NULL OR s->'payroll' IS NULL OR p.id IS NULL OR p.status<>'pending' OR p.action IS DISTINCT FROM 'work.hourly.record' OR p.target_id IS DISTINCT FROM NEW.id OR p.target_version IS DISTINCT FROM 0 OR p.privacy_capability IS DISTINCT FROM 'payroll-accruals.view' OR p.scope IS DISTINCT FROM target OR p.payload IS DISTINCT FROM NEW.input OR p.review_context IS DISTINCT FROM jsonb_build_object('source',s,'plan',NEW.earning_plan) OR NEW.source_snapshot IS DISTINCT FROM s OR NOT public.report_comment_human_verified(NEW.created_by)
 OR NEW.input-ARRAY['personId','from','through','timeZone','currencyId','basis','reference','postedOn','dueOn','period','expenseAccount','liabilityAccount','earningReview','taxReview','roundingReview','reason']<>'{}'::jsonb
 OR NEW.input->>'personId' IS DISTINCT FROM NEW.person_id::text OR NEW.input->>'reference' IS DISTINCT FROM NEW.reference OR NEW.input->>'from' IS DISTINCT FROM NEW.from_on::text OR NEW.input->>'through' IS DISTINCT FROM NEW.through_on::text OR NEW.input->>'timeZone' IS DISTINCT FROM NEW.time_zone OR NEW.input->>'basis' IS DISTINCT FROM NEW.basis OR NEW.input->>'currencyId' IS DISTINCT FROM NEW.currency_id::text OR NEW.input->>'postedOn' IS DISTINCT FROM NEW.posted_on::text OR NEW.input->>'dueOn' IS DISTINCT FROM NEW.due_on::text
 OR NEW.input->'period' IS DISTINCT FROM jsonb_build_object('id',NEW.period_id,'version',NEW.period_version) OR NEW.input->'expenseAccount' IS DISTINCT FROM jsonb_build_object('id',NEW.expense_account,'version',NEW.expense_version) OR NEW.input->'liabilityAccount' IS DISTINCT FROM jsonb_build_object('id',NEW.liability_account,'version',NEW.liability_version)
 OR EXISTS(SELECT 1 FROM unnest(ARRAY['earningReview','taxReview','roundingReview','reason']) k WHERE jsonb_typeof(NEW.input->k) IS DISTINCT FROM 'string' OR length(btrim(NEW.input->>k)) NOT BETWEEN 1 AND 2000)
 OR jsonb_typeof(NEW.earning_plan#>'{gross,minor}') IS DISTINCT FROM 'string' OR NEW.earning_plan#>>'{gross,minor}'!~'^[0-9]{1,38}$' OR(NEW.earning_plan#>>'{gross,minor}')::numeric IS DISTINCT FROM NEW.amount_minor OR jsonb_typeof(NEW.earning_plan->'timeClaims') IS DISTINCT FROM 'array' OR jsonb_array_length(NEW.earning_plan->'timeClaims') NOT BETWEEN 1 AND 1000 THEN RAISE EXCEPTION 'HOURLY_ACCRUAL_EXACT_REVIEW_REQUIRED' USING ERRCODE='23514';END IF;
 IF NEW.created_by=NEW.person_id AND NOT EXISTS(SELECT 1 FROM public.academies WHERE id=NEW.academy_id AND master_person_id=NEW.created_by) THEN RAISE EXCEPTION 'BENEFICIARY_REVIEW_FORBIDDEN' USING ERRCODE='23514';END IF;
 IF NOT public.hourly_plan_valid(NEW.earning_plan,s,NEW.basis,NEW.currency_id,NEW.amount_minor) THEN RAISE EXCEPTION 'HOURLY_PLAN_ARITHMETIC_OR_COVERAGE_INVALID' USING ERRCODE='23514';END IF;
 a=s#>'{accounting,period}';SELECT value INTO e FROM jsonb_array_elements(s#>'{accounting,accounts}') WHERE value->>'id'=NEW.expense_account::text;SELECT value INTO l FROM jsonb_array_elements(s#>'{accounting,accounts}') WHERE value->>'id'=NEW.liability_account::text;
 IF e IS NULL OR l IS NULL OR e->>'kind'<>'expense' OR e->>'role'<>'expense' OR l->>'kind'<>'liability' OR l->>'role'<>'payable' OR e->'active'<>'true'::jsonb OR l->'active'<>'true'::jsonb OR(e->>'version')::integer<>NEW.expense_version OR(l->>'version')::integer<>NEW.liability_version OR e->>'currencyId'<>NEW.currency_id::text OR l->>'currencyId'<>NEW.currency_id::text OR(e->>'currencyVersion')::integer<>NEW.currency_version OR(e->>'unitScale')::integer<>NEW.unit_scale OR(l->>'unitScale')::integer<>NEW.unit_scale
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.earning_plan->'workAllocations') v JOIN public.work_engagements x ON x.academy_id=NEW.academy_id AND x.id=(v->>'engagementId')::uuid WHERE(e->>'hubId' IS NOT NULL AND(e->>'hubId')::uuid IS DISTINCT FROM x.hub_id) OR(l->>'hubId' IS NOT NULL AND(l->>'hubId')::uuid IS DISTINCT FROM x.hub_id))
 OR(a->>'version')::integer<>NEW.period_version OR a->>'state'<>'open' OR NEW.posted_on NOT BETWEEN(a->>'startsOn')::date AND(a->>'endsOn')::date OR(a->>'closedThrough' IS NOT NULL AND NEW.posted_on<=(a->>'closedThrough')::date) THEN RAISE EXCEPTION 'HOURLY_ACCRUAL_MAPPING_INVALID' USING ERRCODE='23514';END IF;
 IF(SELECT sum((v#>>'{gross,minor}')::numeric) FROM jsonb_array_elements(NEW.earning_plan->'sourceAllocations') v) IS DISTINCT FROM NEW.amount_minor OR(SELECT sum((v#>>'{gross,minor}')::numeric) FROM jsonb_array_elements(NEW.earning_plan->'workAllocations') v) IS DISTINCT FROM NEW.amount_minor THEN RAISE EXCEPTION 'HOURLY_ACCRUAL_ALLOCATION_INVALID' USING ERRCODE='23514';END IF;
 NEW.created_at=clock_timestamp();RETURN NEW;
END $$;
CREATE TRIGGER hourly_accrual_guard BEFORE INSERT OR UPDATE ON public.payroll_hourly_accruals FOR EACH ROW EXECUTE FUNCTION public.guard_hourly_accrual();
CREATE FUNCTION public.guard_hourly_claim() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE b record;v jsonb;BEGIN
 SELECT * INTO b FROM public.payroll_hourly_accruals WHERE academy_id=NEW.academy_id AND id=NEW.accrual_id;PERFORM public.lock_hourly_worker(b.person_id);
 IF TG_OP='UPDATE' THEN IF OLD.release_id IS NOT NULL OR NEW.release_id IS NULL OR to_jsonb(NEW)-'release_id' IS DISTINCT FROM to_jsonb(OLD)-'release_id' OR NOT EXISTS(SELECT 1 FROM public.payroll_hourly_voids WHERE academy_id=NEW.academy_id AND id=NEW.release_id AND accrual_id=NEW.accrual_id) THEN RAISE EXCEPTION 'HOURLY_CLAIM_RELEASE_REVIEW_REQUIRED' USING ERRCODE='23514';END IF;RETURN NEW;END IF;
 v=b.earning_plan->'timeClaims'->(NEW.ordinal-1);
 IF b.id IS NULL OR b.void_id IS NOT NULL OR NEW.person_id IS DISTINCT FROM b.person_id OR v IS NULL OR jsonb_typeof(v->'start') IS DISTINCT FROM 'number' OR jsonb_typeof(v->'end') IS DISTINCT FROM 'number' OR(v->>'start')::numeric IS DISTINCT FROM NEW.start_ms::numeric OR(v->>'end')::numeric IS DISTINCT FROM NEW.end_ms::numeric OR NEW.start_ms<(b.source_snapshot#>>'{payroll,windowStartMilliseconds}')::bigint OR NEW.end_ms>(b.source_snapshot#>>'{payroll,windowEndMilliseconds}')::bigint THEN RAISE EXCEPTION 'HOURLY_CLAIM_PLAN_REQUIRED' USING ERRCODE='23514';END IF;RETURN NEW;
END $$;
CREATE TRIGGER hourly_claim_guard BEFORE INSERT OR UPDATE ON public.payroll_hourly_claims FOR EACH ROW EXECUTE FUNCTION public.guard_hourly_claim();
CREATE FUNCTION public.guard_hourly_entry_source() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE b record;BEGIN
 SELECT * INTO b FROM public.payroll_hourly_accruals WHERE academy_id=NEW.academy_id AND id=NEW.accrual_id;PERFORM public.lock_hourly_worker(b.person_id);
 IF TG_OP='UPDATE' THEN IF OLD.release_id IS NOT NULL OR NEW.release_id IS NULL OR to_jsonb(NEW)-'release_id' IS DISTINCT FROM to_jsonb(OLD)-'release_id' OR NOT EXISTS(SELECT 1 FROM public.payroll_hourly_voids WHERE academy_id=NEW.academy_id AND id=NEW.release_id AND accrual_id=NEW.accrual_id) THEN RAISE EXCEPTION 'HOURLY_SOURCE_RELEASE_REVIEW_REQUIRED' USING ERRCODE='23514';END IF;RETURN NEW;END IF;
 IF b.id IS NULL OR b.void_id IS NOT NULL OR NEW.person_id IS DISTINCT FROM b.person_id OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(b.earning_plan->'sourceIdentities') x WHERE x->>'entryId'=NEW.entry_id::text AND(x->>'entryVersion')::integer=NEW.entry_version AND x->>'pricingFingerprint'=NEW.pricing_fingerprint) THEN RAISE EXCEPTION 'HOURLY_SOURCE_IDENTITY_REQUIRED' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT 1 FROM public.payroll_hourly_entry_sources WHERE academy_id=NEW.academy_id AND entry_id=NEW.entry_id AND release_id IS NULL AND(pricing_fingerprint<>NEW.pricing_fingerprint OR entry_version<>NEW.entry_version)) THEN RAISE EXCEPTION 'HOURLY_SOURCE_CORRECTION_REQUIRED' USING ERRCODE='23514';END IF;RETURN NEW;
END $$;
CREATE TRIGGER hourly_entry_source_guard BEFORE INSERT OR UPDATE ON public.payroll_hourly_entry_sources FOR EACH ROW EXECUTE FUNCTION public.guard_hourly_entry_source();
CREATE FUNCTION public.guard_hourly_void() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE p record;s jsonb;w record;target jsonb;BEGIN
 SELECT * INTO p FROM public.approval_requests WHERE academy_id=NEW.academy_id AND id=NEW.approval_id;s=public.hourly_void_source(NEW.accrual_id,(p.payload#>>'{period,id}')::uuid);
 SELECT person_id,hub_id INTO w FROM public.work_engagements WHERE academy_id=NEW.academy_id AND person_id=(s#>>'{before,personId}')::uuid ORDER BY id LIMIT 1;
 target=jsonb_build_object('all',false,'hubs','[]'::jsonb,'people',jsonb_build_array(jsonb_build_object('id',w.person_id,'hubId',w.hub_id)),'workContext',jsonb_build_object('personId',w.person_id,'hubId',w.hub_id));
 IF s IS NULL OR p.id IS NULL OR p.status<>'pending' OR p.action IS DISTINCT FROM 'work.hourly.void' OR p.target_id IS DISTINCT FROM NEW.id OR p.target_version IS DISTINCT FROM 0 OR p.privacy_capability IS DISTINCT FROM 'payroll-accruals.view' OR p.scope IS DISTINCT FROM target OR p.payload IS DISTINCT FROM jsonb_build_object('accrualId',NEW.accrual_id,'period',p.payload->'period','postedOn',p.payload->'postedOn','reason',NEW.reason) OR p.review_context IS DISTINCT FROM s OR NEW.source_snapshot IS DISTINCT FROM s OR s#>>'{before,voidId}' IS NOT NULL OR(p.payload->>'postedOn')::date<(s#>>'{before,postedOn}')::date OR NOT public.report_comment_human_verified(NEW.created_by) THEN RAISE EXCEPTION 'HOURLY_VOID_EXACT_REVIEW_REQUIRED' USING ERRCODE='23514';END IF;
 IF NEW.created_by=(s#>>'{before,personId}')::uuid AND NOT EXISTS(SELECT 1 FROM public.academies WHERE id=NEW.academy_id AND master_person_id=NEW.created_by) THEN RAISE EXCEPTION 'BENEFICIARY_REVIEW_FORBIDDEN' USING ERRCODE='23514';END IF;NEW.created_at=clock_timestamp();RETURN NEW;
END $$;
CREATE TRIGGER hourly_void_guard BEFORE INSERT ON public.payroll_hourly_voids FOR EACH ROW EXECUTE FUNCTION public.guard_hourly_void();
CREATE FUNCTION public.hourly_posting_complete() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE j record;b record;s jsonb;p record;BEGIN
 SELECT * INTO j FROM public.finance_journals WHERE academy_id=NEW.academy_id AND id=NEW.id;
 IF TG_TABLE_NAME='payroll_hourly_accruals' THEN
  b=NEW;s=public.hourly_accrual_source(NEW.input,NEW.id);
  IF s IS DISTINCT FROM NEW.source_snapshot OR j.id IS NULL OR j.period_id IS DISTINCT FROM NEW.period_id OR j.period_version IS DISTINCT FROM NEW.period_version OR j.posted_on IS DISTINCT FROM NEW.posted_on OR j.reverses_id IS NOT NULL OR j.description IS DISTINCT FROM 'Recorded hourly gross accrual' OR j.reference IS DISTINCT FROM 'PAYROLL-HOURLY'
  OR(SELECT count(*) FROM public.payroll_hourly_claims WHERE academy_id=NEW.academy_id AND accrual_id=NEW.id AND release_id IS NULL)<>jsonb_array_length(NEW.earning_plan->'timeClaims') OR(SELECT count(*) FROM public.payroll_hourly_entry_sources WHERE academy_id=NEW.academy_id AND accrual_id=NEW.id AND release_id IS NULL)<>jsonb_array_length(NEW.earning_plan->'sourceIdentities') THEN RAISE EXCEPTION 'HOURLY_ACCRUAL_COMPLETE_SOURCE_REQUIRED' USING ERRCODE='23514';END IF;
 ELSE
  SELECT * INTO b FROM public.payroll_hourly_accruals WHERE academy_id=NEW.academy_id AND id=NEW.accrual_id;SELECT * INTO p FROM public.approval_requests WHERE academy_id=NEW.academy_id AND id=NEW.approval_id;s=public.hourly_void_source(b.id,j.period_id);
  IF b.void_id IS DISTINCT FROM NEW.id OR j.id IS NULL OR j.reverses_id IS DISTINCT FROM b.id OR j.description IS DISTINCT FROM 'Correction of recorded hourly accrual' OR j.reference IS DISTINCT FROM 'PAYROLL-HOURLY-CORRECTION' OR j.period_id IS DISTINCT FROM(p.payload#>>'{period,id}')::uuid OR j.period_version IS DISTINCT FROM(p.payload#>>'{period,version}')::integer OR j.posted_on IS DISTINCT FROM(p.payload->>'postedOn')::date OR(s->'before')-'voidId' IS DISTINCT FROM(NEW.source_snapshot->'before')-'voidId' OR s->'accounting' IS DISTINCT FROM NEW.source_snapshot->'accounting' OR EXISTS(SELECT 1 FROM public.payroll_hourly_claims WHERE academy_id=NEW.academy_id AND accrual_id=b.id AND release_id IS DISTINCT FROM NEW.id) OR EXISTS(SELECT 1 FROM public.payroll_hourly_entry_sources WHERE academy_id=NEW.academy_id AND accrual_id=b.id AND release_id IS DISTINCT FROM NEW.id) THEN RAISE EXCEPTION 'HOURLY_VOID_COMPLETE_REQUIRED' USING ERRCODE='23514';END IF;
 END IF;
 IF j.approval_id IS DISTINCT FROM NEW.approval_id OR j.posted_by IS DISTINCT FROM NEW.created_by OR j.purpose IS DISTINCT FROM 'activity' OR j.line_count<>2
 OR NOT EXISTS(SELECT 1 FROM public.finance_journal_lines WHERE academy_id=NEW.academy_id AND journal_id=NEW.id AND line_number=1 AND account_id=b.expense_account AND account_version=b.expense_version AND side=CASE WHEN TG_TABLE_NAME='payroll_hourly_accruals' THEN 'debit' ELSE 'credit' END AND amount_minor=b.amount_minor AND note='')
 OR NOT EXISTS(SELECT 1 FROM public.finance_journal_lines WHERE academy_id=NEW.academy_id AND journal_id=NEW.id AND line_number=2 AND account_id=b.liability_account AND account_version=b.liability_version AND side=CASE WHEN TG_TABLE_NAME='payroll_hourly_accruals' THEN 'credit' ELSE 'debit' END AND amount_minor=b.amount_minor AND note='') THEN RAISE EXCEPTION 'HOURLY_EXACT_LEDGER_REQUIRED' USING ERRCODE='23514';END IF;RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER hourly_posting_complete AFTER INSERT ON public.payroll_hourly_accruals DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.hourly_posting_complete();
CREATE CONSTRAINT TRIGGER hourly_void_complete AFTER INSERT ON public.payroll_hourly_voids DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.hourly_posting_complete();
CREATE CONSTRAINT TRIGGER hourly_reviewed AFTER INSERT ON public.payroll_hourly_accruals DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.reviewed_approval_complete();
CREATE CONSTRAINT TRIGGER hourly_void_reviewed AFTER INSERT ON public.payroll_hourly_voids DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.reviewed_approval_complete();
CREATE FUNCTION public.hourly_effect_required() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN
 IF NEW.status='applied' AND((NEW.action='work.hourly.record' AND NOT EXISTS(SELECT 1 FROM public.payroll_hourly_accruals WHERE academy_id=NEW.academy_id AND id=NEW.target_id AND approval_id=NEW.id AND created_by=NEW.reviewer_id)) OR(NEW.action='work.hourly.void' AND NOT EXISTS(SELECT 1 FROM public.payroll_hourly_voids WHERE academy_id=NEW.academy_id AND id=NEW.target_id AND approval_id=NEW.id AND created_by=NEW.reviewer_id))) THEN RAISE EXCEPTION 'HOURLY_EFFECT_REQUIRED' USING ERRCODE='23514';END IF;RETURN NULL;END $$;
CREATE CONSTRAINT TRIGGER hourly_effect_required AFTER INSERT OR UPDATE ON public.approval_requests DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.hourly_effect_required();
CREATE FUNCTION public.hourly_reversal_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN
 IF EXISTS(SELECT 1 FROM public.payroll_hourly_accruals WHERE academy_id=NEW.academy_id AND id=NEW.reverses_id) AND NOT EXISTS(SELECT 1 FROM public.payroll_hourly_voids v JOIN public.approval_requests p ON p.academy_id=v.academy_id AND p.id=v.approval_id WHERE v.academy_id=NEW.academy_id AND v.id=NEW.id AND v.accrual_id=NEW.reverses_id AND p.action='work.hourly.void' AND p.target_id=NEW.id AND NEW.approval_id=p.id) THEN RAISE EXCEPTION 'HOURLY_CORRECTION_WORKFLOW_REQUIRED' USING ERRCODE='23514';END IF;RETURN NEW;END $$;
CREATE TRIGGER hourly_reversal_guard BEFORE INSERT ON public.finance_journals FOR EACH ROW WHEN(NEW.reverses_id IS NOT NULL) EXECUTE FUNCTION public.hourly_reversal_guard();
CREATE FUNCTION public.hourly_approval_privacy() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE s jsonb;w jsonb;e jsonb;a jsonb;scope jsonb;cap text;BEGIN
 IF NEW.action='work.hourly.record' THEN s=NEW.review_context#>'{source,payroll}';
 ELSE SELECT source_snapshot->'payroll' INTO s FROM public.payroll_hourly_accruals WHERE academy_id=NEW.academy_id AND id=(NEW.payload->>'accrualId')::uuid;END IF;
 IF s IS NULL OR jsonb_array_length(s->'work')=0 THEN NEW.privacy_bindings=NEW.privacy_bindings||jsonb_build_array(jsonb_build_object('unresolved',true));RETURN NEW;END IF;
 FOR w IN SELECT value FROM jsonb_array_elements(s->'work') LOOP
  scope=jsonb_build_object('all',false,'hubs','[]'::jsonb,'people',jsonb_build_array(jsonb_build_object('id',w->>'person_id','hubId',w->'hub_id')),'workContext',jsonb_build_object('personId',w->>'person_id','hubId',w->'hub_id'));
  FOREACH cap IN ARRAY ARRAY['payroll-accruals.view','work-pay.view','pay-periods.view','payroll-preparations.view'] LOOP NEW.privacy_bindings=NEW.privacy_bindings||jsonb_build_array(jsonb_build_object('capability',cap,'scope',scope));END LOOP;
 END LOOP;
 FOR e IN SELECT value FROM jsonb_array_elements(s->'entries') LOOP
  scope=jsonb_build_object('all',false,'hubs','[]'::jsonb,'classes',jsonb_build_array(jsonb_build_object('id',e->>'class_id','hubId',e->'hub_id')));
  FOREACH cap IN ARRAY ARRAY['session-reports.view','attendance.view','rosters.view','session-time.view','staff.view','files.view','session-evidence.view'] LOOP NEW.privacy_bindings=NEW.privacy_bindings||jsonb_build_array(jsonb_build_object('capability',cap,'scope',scope));END LOOP;
 END LOOP;
 IF NEW.action='work.hourly.record' THEN s=NEW.review_context#>'{source,accounting}';ELSE s=NEW.review_context->'accounting';END IF;
 FOR a IN SELECT value FROM jsonb_array_elements(s->'accounts') LOOP
  scope=CASE WHEN a->>'hubId' IS NULL THEN jsonb_build_object('all',true,'hubs','[]'::jsonb) ELSE jsonb_build_object('all',false,'hubs',jsonb_build_array(a->>'hubId')) END;
  FOREACH cap IN ARRAY ARRAY['accounts.view','journals.view'] LOOP NEW.privacy_bindings=NEW.privacy_bindings||jsonb_build_array(jsonb_build_object('capability',cap,'scope',scope));END LOOP;
 END LOOP;RETURN NEW;
 EXCEPTION WHEN invalid_text_representation THEN NEW.privacy_bindings=NEW.privacy_bindings||jsonb_build_array(jsonb_build_object('unresolved',true));RETURN NEW;
END $$;
CREATE TRIGGER zz_hourly_approval_privacy BEFORE INSERT ON public.approval_requests FOR EACH ROW WHEN(NEW.action IN('work.hourly.record','work.hourly.void')) EXECUTE FUNCTION public.hourly_approval_privacy();
REVOKE ALL ON FUNCTION public.hourly_approval_privacy() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.guard_hourly_entry_source() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.lock_hourly_worker(uuid),public.hourly_accounting_source(uuid,uuid,uuid),public.hourly_accrual_source(jsonb,uuid),public.hourly_void_source(uuid,uuid),public.hourly_plan_valid(jsonb,jsonb,text,uuid,numeric),public.guard_hourly_accrual(),public.guard_hourly_claim(),public.guard_hourly_void(),public.hourly_posting_complete(),public.hourly_effect_required(),public.hourly_reversal_guard() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.lock_hourly_worker(uuid),public.hourly_accounting_source(uuid,uuid,uuid),public.hourly_accrual_source(jsonb,uuid),public.hourly_void_source(uuid,uuid),public.hourly_plan_valid(jsonb,jsonb,text,uuid,numeric) TO kavosh_runtime;
CREATE OR REPLACE FUNCTION public.schema_revision() RETURNS integer LANGUAGE sql IMMUTABLE AS $$ SELECT 98 $$;
